from collections import deque

def bfs_color(adj, color):
    for start in range(12):
        if color[start] == -1:
            color[start] = 0
            queue = deque([start])
            while queue:
                node = queue.popleft()
                for nb in adj[node]:
                    if color[nb] == -1:
                        color[nb] = 1 - color[node]
                        queue.append(nb)
                    elif color[nb] == color[node]:
                        return False
    return True

